export function solve(input) {
  const d = input;
  const out = [];
  const walk = (n, anc) => {
    const chain = anc.concat(n.tag);
    if (
      chain.length >= d.tags.length &&
      d.tags.every((tag, i) => chain[chain.length - d.tags.length + i] === tag)
    )
      out.push(n.id);
    for (const c of n.children) walk(c, chain);
  };
  walk(d.tree, []);
  return out;
}

referenceSolutions.typescript:
type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const out: string[] = [];
  const walk = (n: any, anc: string[]): void => {
    const chain = anc.concat(n.tag);
    if (
      chain.length >= d.tags.length &&
      d.tags.every((tag: string, i: number) => chain[chain.length - d.tags.length + i] === tag)
    )
      out.push(n.id);
    for (const c of n.children) walk(c, chain);
  };
  walk(d.tree, []);
  return out;
}
